mapper.update:
update borrow
set userId = #{userid,jdbcType=INTEGER},
  bookId = #{bookid,jdbcType=INTEGER},
  borrowTime = #{borrowtime,jdbcType=TIMESTAMP},
  returnTime = #{returntime,jdbcType=TIMESTAMP}
where borrowId = #{borrowid,jdbcType=INTEGER}

mapper.select:
select borrowId, borrow.userId, borrow.bookId, borrowTime, returnTime, renewCount, dueTime, userName, bookName from borrow, user, book_info where borrow.userId = user.userId and borrow.bookId = book_info.bookId
and userName like concat('%',#{username},'%')
and bookName like concat('%',#{bookname},'%')
and borrow.userId = #{userid}
order by borrow.borrowTime desc limit #{begin}, #{size}
